content:
:root {
  --primary-color: #3b82f6;
  --primary-hover: #2563eb;
  --correct-color: #22c55e;
  --incorrect-color: #ef4444;
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  --text-color: #1e293b;
  --text-muted: #64748b;
  --border-color: #e2e8f0;
  --radius: 12px;
  --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
}

body {
  background-color: var(--bg-color);
  color: var(--text-color);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
}

.app-container {
  width: 100%;
  max-width: 600px;
  margin: 0 auto;
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.progress-bar {
  width: 100%;
  height: 8px;
  background-color: var(--border-color);
  border-radius: 4px;
  overflow: hidden;
  margin-bottom: 10px;
}

.progress-bar-fill {
  height: 100%;
  background-color: var(--primary-color);
  transition: width 0.3s ease;
}

.quiz-card {
  background-color: var(--card-bg);
  border-radius: var(--radius);
  padding: 24px;
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.question-title {
  font-size: 1.25rem;
  font-weight: 700;
  line-height: 1.5;
  color: var(--text-color);
}

.options-container {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.option-btn {
  background-color: var(--card-bg);
  border: 2px solid var(--border-color);
  border-radius: var(--radius);
  padding: 14px 18px;
  font-size: 1rem;
  text-align: left;
  cursor: pointer;
  transition: all 0.2s ease;
  color: var(--text-color);
  font-weight: 500;
}

.option-btn:hover:not(:disabled) {
  border-color: var(--primary-color);
  background-color: #eff6ff;
}

.option-btn:disabled {
  cursor: default;
}

.option-btn.correct {
  background-color: #dcfce7;
  border-color: var(--correct-color);
  color: #166534;
}

.option-btn.incorrect {
  background-color: #fee2e2;
  border-color: var(--incorrect-color);
  color: #991b1b;
}

.explanation {
  background-color: #f1f5f9;
  border-left: 4px solid var(--primary-color);
  padding: 14px;
  border-radius: 0 var(--radius) var(--radius) 0;
  font-size: 0.95rem;
  line-height: 1.6;
  color: var(--text-muted);
}

.btn-primary {
  background-color: var(--primary-color);
  color: white;
  border: none;
  border-radius: var(--radius);
  padding: 14px 20px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.2s ease;
  width: 100%;
  text-align: center;
}

.btn-primary:hover {
  background-color: var(--primary-hover);
}

.result-card {
  background-color: var(--card-bg);
  border-radius: var(--radius);
  padding: 32px;
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 24px;
}

.score-display {
  font-size: 2rem;
  font-weight: 700;
  color: var(--primary-color);
}

@media (max-width: 480px) {
  .app-container {
    padding: 12px;
  }

  .quiz-card, .result-card {
    padding: 16px;
  }

  .question-title {
    font-size: 1.1rem;
  }
}

export interface Question {
  id: number;
  text: string;
  options: string[];
  correctIndex: number;
  explanation: string;
}

export interface QuizState {
  currentIndex: number;
  selectedOption: number | null;
  score: number;
  isAnswered: boolean;
  isFinished: boolean;
}

import { Question } from '../types';

interface QuizCardProps {
  question: Question;
  selectedOption: number | null;
  isAnswered: boolean;
  onSelectOption: (index: number) => void;
  onNext: () => void;
}

export default function QuizCard({
  question,
  selectedOption,
  isAnswered,
  onSelectOption,
  onNext,
}: QuizCardProps) {
  const { text, options, correctIndex, explanation } = question;

  return (
    <div className="quiz-card">
      <h2 className="question-title">{text}</h2>
      <div className="options-container">
        {options.map((option, index) => {
          let btnClass = 'option-btn';
          if (isAnswered) {
            if (index === correctIndex) {
              btnClass += ' correct';
            } else if (index === selectedOption) {
              btnClass += ' incorrect';
            }
          }
          return (
            <button
              key={index}
              className={btnClass}
              onClick={() => !isAnswered && onSelectOption?.(index)}
              disabled={isAnswered}
            >
              {option}
            </button>
          );
        })}
      </div>
      {isAnswered && (
        <>
          <div className="explanation">
            <p>{explanation}</p>
          </div>
          <button className="btn-primary" onClick={onNext}>
            次の問題へ
          </button>
        </>
      )}
    </div>
  );
}

interface ResultCardProps {
  score: number;
  total: number;
  onRestart: () => void;
}

export default function ResultCard({ score, total, onRestart }: ResultCardProps) {
  return (
    <div className="result-card">
      <h2>クイズ終了！</h2>
      <p>お疲れ様でした。あなたのスコアはこちらです：</p>
      <div className="score-display">
        {score} / {total} 問正解
      </div>
      <button className="btn-primary" onClick={onRestart}>
        もう一度挑戦する
      </button>
    </div>
  );
}

import { useState } from 'react';
import { Question, QuizState } from './types';
import QuizCard from './components/QuizCard';
import ResultCard from './components/ResultCard';

const questions: Question[] = [
  {
    id: 1,
    text: '日本で一番面積が大きい都道府県はどこ？',
    options: ['岩手県', '北海道', '新潟県', '長野県'],
    correctIndex: 1,
    explanation: '北海道は日本で最も面積が大きい都道府県で、日本の総面積の約22%を占めています。',
  },
  {
    id: 2,
    text: '日本で一番高い山の名前は？',
    options: ['北岳', '槍ヶ岳', '富士山', '穂高岳'],
    correctIndex: 2,
    explanation: '富士山は標高3,776.12mで、日本最高峰の独立峰です。静岡県と山梨県にまたがっています。',
  },
  {
    id: 3,
    text: '日本最南端に位置する島（有人島・無人島含む領土内）はどこ？',
    options: ['沖ノ鳥島', '与那国島', '波照間島', '硫黄島'],
    correctIndex: 0,
    explanation: '日本の領土としての最南端は沖ノ鳥島です。東京都小笠原村に属しています。',
  },
  {
    id: 4,
    text: '琵琶湖がある都道府県はどこ？',
    options: ['三重県', '滋賀県', '京都府', '岐阜県'],
    correctIndex: 1,
    explanation: '琵琶湖は滋賀県にある日本最大の湖で、近畿地方の重要な水源となっています。',
  },
  {
    id: 5,
    text: '日本で一番長い川（信濃川）の源流または流域に含まれない都道府県はどれ？',
    options: ['長野県', '新潟県', '群馬県', '富山県'],
    correctIndex: 3,
    explanation: '信濃川（千曲川）は長野県、群馬県、新潟県を流れますが、富山県は流れていません。',
  },
];

export default function App() {
  const [state, setState] = useState<QuizState>({
    currentIndex: 0,
    selectedOption: null,
    score: 0,
    isAnswered: false,
    isFinished: false,
  });

  const handleSelectOption = (index: number) => {
    if (state.isAnswered || state.isFinished) return;

    const currentQuestion = questions[state.currentIndex];
    const isCorrect = index === currentQuestion.correctIndex;

    setState((prev) => ({
      ...prev,
      selectedOption: index,
      score: isCorrect ? prev.score + 1 : prev.score,
      isAnswered: true,
    }));
  };

  const handleNext = () => {
    if (state.currentIndex + 1 < questions.length) {
      setState((prev) => ({
        ...prev,
        currentIndex: prev.currentIndex + 1,
        selectedOption: null,
        isAnswered: false,
      }));
    } else {
      setState((prev) => ({
        ...prev,
        isFinished: true,
      }));
    }
  };

  const handleRestart = () => {
    setState({
      currentIndex: 0,
      selectedOption: null,
      score: 0,
      isAnswered: false,
      isFinished: false,
    });
  };

  const progressPercent = ((state.currentIndex + (state.isFinished ? 1 : 0)) / questions.length) * 100;

  return (
    <div className="app-container">
      {!state.isFinished && (
        <>
          <div className="progress-bar">
            <div
              className="progress-bar-fill"
              style={{ width: `${progressPercent}%` }}
            ></div>
          </div>
          <QuizCard
            question={questions[state.currentIndex]}
            selectedOption={state.selectedOption}
            isAnswered={state.isAnswered}
            onSelectOption={handleSelectOption}
            onNext={handleNext}
          />
        </>
      )}
      {state.isFinished && (
        <ResultCard
          score={state.score}
          total={questions.length}
          onRestart={handleRestart}
        />
      )}
    </div>
  );
}
